import {spacedRecommendations} from './prediction-spacing.mjs';
export const calendarKey='mecanica.practice-calendar.v1';
export const dateKey=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const fromKey=k=>{const [y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d);};
export function createCalendarStore(storage){let state={goal:3,days:{}},warning='';try{const raw=storage.getItem(calendarKey);if(raw){const x=JSON.parse(raw);if(!Number.isInteger(x.goal)||x.goal<1||x.goal>20||!x.days)throw Error();state={goal:x.goal,days:{}};for(const [k,v]of Object.entries(x.days))if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Array.isArray(v.ids)&&Number.isInteger(v.target)&&v.target>=1&&v.target<=20)state.days[k]={target:v.target,ids:[...new Set(v.ids.filter(id=>typeof id==='string'))]};}}catch{warning='No se pudo leer el calendario guardado; se usa la sesión actual.';}
 const save=()=>{if(warning)return;try{storage.setItem(calendarKey,JSON.stringify(state));}catch{warning='El calendario solo se conservará en esta sesión: almacenamiento no disponible.';}};
 return {state:()=>structuredClone(state),warning:()=>warning,sync(rows,now=new Date()){let changed=false;for(const r of rows){if(!r.resolved||r.revealed)continue;const d=new Date(r.completedAt||r.date);if(!Number.isFinite(+d)||d>now)continue;const key=dateKey(d);if(!state.days[key]){state.days[key]={target:state.goal,ids:[]};changed=true;}if(!state.days[key].ids.includes(r.id)){state.days[key].ids.push(r.id);changed=true;}}if(changed)save();},setGoal(n,now=new Date()){if(!Number.isInteger(n)||n<1||n>20)return false;state.goal=n;const key=dateKey(now);state.days[key]??={ids:[],target:n};state.days[key].target=n;save();return true;}};
}
export function dailyProgress(state,now=new Date()){const key=dateKey(now),today=state.days[key],count=today?.ids.length||0,target=today?.target||state.goal;const qualified=k=>!!state.days[k]&&state.days[k].ids.length>=state.days[k].target;let cursor=fromKey(key);if(!qualified(key))cursor.setDate(cursor.getDate()-1);let streak=0;while(qualified(dateKey(cursor))){streak++;cursor.setDate(cursor.getDate()-1);}let best=0,run=0,previous=null;for(const k of Object.keys(state.days).sort()){if(!qualified(k)){run=0;previous=null;continue;}const d=fromKey(k),prev=new Date(+d);prev.setDate(prev.getDate()-1);run=previous===dateKey(prev)?run+1:1;best=Math.max(best,run);previous=k;}return {count,target,remaining:Math.max(0,target-count),streak,best};}
export function createPracticeCalendar(host,storage){const store=createCalendarStore(storage);let month=new Date(),selected=dateKey(new Date()),context;
 function render(){if(!context)return;const {rows,ready,start,startFresh}=context,now=new Date(),today=dateKey(now);store.sync(rows,now);const state=store.state(),progress=dailyProgress(state,now),recs=spacedRecommendations(rows,now),due=recs.filter(r=>r.isDue);host.replaceChildren();
 const el=(tag,text,parent=host)=>{const n=document.createElement(tag);if(text)n.textContent=text;parent.append(n);return n;};el('h3','Tu calendario de práctica');el('p','La meta cuenta preguntas resueltas por ti, con o sin pistas; consultar la solución no suma. La racha cuenta días consecutivos con la meta cumplida. Cambiar la meta afecta hoy y los próximos días, sin cambiar los días anteriores.');
 const stats=el('div',null);stats.className='calendar-stats';el('strong','Hoy: '+progress.count+' / '+progress.target,stats);el('strong','Racha: '+progress.streak+' días',stats);el('strong','Mejor: '+progress.best+' días',stats);const meter=el('progress',null,stats);meter.max=progress.target;meter.value=Math.min(progress.count,progress.target);meter.setAttribute('aria-label','Avance hacia la meta diaria');
 const form=el('form');form.className='actions';const label=el('label','Meta diaria (1–20 preguntas) ',form),input=el('input',null,label);input.type='number';input.min=1;input.max=20;input.step=1;input.required=true;input.value=progress.target;input.id='dailyGoal';el('button','Guardar meta',form).type='submit';form.onsubmit=e=>{e.preventDefault();if(store.setGoal(Number(input.value)))render();};
 const action=el('button',progress.remaining?'Completar mi meta · faltan '+progress.remaining:'Meta cumplida · seguir practicando');action.id='dailyChallenge';action.disabled=!ready;action.onclick=()=>{const pool=due.length?due:recs;if(pool.length)start(pool.slice(0,3).map(r=>r.signal));else startFresh();};el('p',due.length+' señales pendientes para hoy. La meta y los repasos pendientes son objetivos distintos: completar una no borra los otros.');if(store.warning())el('p',store.warning());
 const nav=el('div');nav.className='actions';const prev=el('button','← Mes anterior',nav),title=el('strong',month.toLocaleDateString('es-CO',{month:'long',year:'numeric'}),nav),next=el('button','Mes siguiente →',nav);prev.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);render();};next.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);render();};const home=el('button','Hoy',nav);home.onclick=()=>{month=new Date();selected=today;render();};
 const grid=el('div');grid.className='practice-month';grid.setAttribute('aria-label','Calendario de repasos');for(const name of ['L','M','X','J','V','S','D'])el('span',name,grid);const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7;for(let i=0;i<offset;i++)el('span',null,grid);const total=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();
 for(let n=1;n<=total;n++){const d=new Date(month.getFullYear(),month.getMonth(),n),key=dateKey(d),record=state.days[key],planned=recs.filter(r=>(r.isDue?today:dateKey(new Date(r.due)))===key),achieved=record&&record.ids.length>=record.target;const b=el('button',null,grid);b.className=achieved?'achieved':'';b.setAttribute('aria-pressed',String(selected===key));if(key===today)b.setAttribute('aria-current','date');el('strong',String(n),b);el('small',achieved?'✓ Meta':record?record.ids.length+'/'+record.target:'',b);if(planned.length)el('small','↻ '+planned.length,b);b.setAttribute('aria-label',d.toLocaleDateString('es-CO')+(achieved?' · meta cumplida':'')+' · '+planned.length+' repasos previstos');b.onclick=()=>{selected=key;render();};}
 const panel=el('div');panel.className='calendar-day';el('h4',fromKey(selected).toLocaleDateString('es-CO',{weekday:'long',year:'numeric',month:'long',day:'numeric'}),panel);const past=state.days[selected];el('p',past?past.ids.length+' preguntas resueltas · meta '+past.target:'Sin preguntas guardadas para este día.',panel);const planned=recs.filter(r=>(r.isDue?today:dateKey(new Date(r.due)))===selected);if(!planned.length)el('p','No hay repasos previstos en esta fecha.',panel);for(const r of planned){const b=el('button',r.label+' · '+(selected===today?'Practicar':'Adelantar repaso'),panel);b.disabled=!ready;b.onclick=()=>start([r.signal]);}el('p','↻ indica la cantidad de señales a repasar. Los atrasados se agrupan en hoy. Las fechas futuras son estimaciones que cambian al practicar. Los días anteriores muestran metas alcanzadas; no reconstruyen antiguos vencimientos. El historial previo se incorpora con la meta configurada al importarlo. Datos locales del navegador.');
 }
 return {update(value){context=value;render();}};
}
